record_usage:
def record_usage(state, key, model, tokens) do
  if not valid_key(state, key), do: raise("key must be a non-empty string")
  if not valid_model(state, model), do: raise("model must be a non-empty string")
  if not valid_tokens(state, tokens), do: raise("tokens must be a positive whole number")
  used = usage(state, key)
  quota = Map.get(Map.get(state, "quotas", %{}), key)
  if quota != nil and used + tokens > quota, do: raise("quota exceeded for key #{key}")
  calls = Map.get(state, "calls", []) ++ [%{"key" => key, "model" => model, "tokens" => tokens}]
  new_state = Map.put(state, "calls", calls)
  {usage(new_state, key), new_state}
end

set_price:
def set_price(state, model, cents_per_1k_tokens) do
  if not (is_number(cents_per_1k_tokens) and cents_per_1k_tokens >= 0), do: raise("price must be a non-negative number")
  {cents_per_1k_tokens, Map.put(state, "prices", Map.put(Map.get(state, "prices", %{}), model, cents_per_1k_tokens))}
end

set_quota:
def set_quota(state, key, tokens) do
  if not (is_number(tokens) and tokens >= 0), do: raise("quota must be a non-negative number")
  if usage(state, key) > tokens, do: raise("key #{key} has already used more than #{tokens} tokens")
  {tokens, Map.put(state, "quotas", Map.put(Map.get(state, "quotas", %{}), key, tokens))}
end
